"""Scientific review corrections: produced water, compression, heat and power."""
from revise_foundations_scientific_text import revise, BOOK, ledger
import re, json, math

def R(ch, key, old, new, issue=None, sources=None):
    revise(ch, ch+'_'+key, old, new, issue or key.replace('_',' '), sources or ['Dimensional analysis and conservation-law derivation; reviewed against the cited chapter references'])

def S(ch, key, pattern, new, issue=None, sources=None):
    if any(x['id']==ch+'_'+key for x in ledger): return
    text=next((BOOK/'chapters').glob(ch+'*/chapter.md')).read_text(encoding='utf-8')
    m=re.search(pattern,text,re.S)
    if not m: raise ValueError(ch+'_'+key)
    R(ch,key,m[0],new,issue,sources)

S('ch13','production_totals',r'For every barrel of oil produced globally,.*?per year\.', 'Produced-water volumes depend strongly on field age, reservoir connectivity and injection strategy; global water-to-oil ratios and annual NCS totals require a dated inventory and are not design inputs for an individual facility.')
S('ch13','brine_density',r'The density of produced water increases with salinity.*?density of the salt species\.',r'''Brine density depends on temperature, pressure and dissolved composition. The previous molecular-weight/solid-density expression is dimensionally unsuitable for a solution. Calculate density from a validated electrolyte property model or measured brine data. For converting a measured salt concentration to mass fraction, the exact definition is

$$w_s=\frac{C_s}{\rho_{\mathrm{brine}}}$$

with both $C_s$ and $\rho_{\mathrm{brine}}$ in kg/m³; 1 mg/L = 0.001 kg/m³. For example, 100,000 mg/L in brine of density 1,070 kg/m³ corresponds to $w_s=0.09346$, not 10 wt%. An iterative density/composition calculation may be needed if only TDS is known.''')
R('ch13','ospar_method','The 30 mg/L limit is measured by the reference method ISO 9377-2 (hydrocarbon oil index using GC-FID after solvent extraction). Individual measurements may exceed 30 mg/L provided the monthly weighted average is met:',r'The OSPAR reference is Agreement 2005-15, based on a modified ISO 9377-2 extraction/GC-FID procedure. The 30 mg/L performance standard is a flow-weighted monthly average; site permits can impose additional sample, alarm or discharge-stop conditions.\cite{foundationOSPARmethod} The averaging calculation is:', sources=['https://www.ospar.org/documents?v=32591'])
R('ch13','ospar_oldgoal','**Zero harmful discharge**: OSPAR\'s goal is to achieve zero discharge of hazardous substances by 2020 (aspirational)', '**Hazardous-substance reduction**: apply the current OSPAR strategy and the installation permit; the historical 2020 aspiration is not a current discharge authorization')
S('ch13','cyclone_dimension',r'The cut size \$d_\{50\}\$.*?volumetric flow rate\.',r'''A cut-size correlation must be calibrated for the actual liner geometry and droplet population. A dimensionally consistent relative screening relation for a fixed liner is

$$\frac{d_{50}}{d_{50,0}}\simeq\left[\frac{\mu_w}{\mu_{w,0}}\frac{\Delta\rho_0}{\Delta\rho}\frac{Q_0}{Q}\right]^{1/2}.$$

All ratios are dimensionless. It extrapolates a measured reference cut size rather than predicting an absolute cut size from an undefined geometry constant. Reject split, turbulence-induced breakup and the tested flow envelope also matter.''')
R('ch13','pdr_definition','The ratio of the reject-side pressure drop to the feed-side pressure drop.',r'$\mathrm{PDR}=(P_{\mathrm{feed}}-P_{\mathrm{reject}})/(P_{\mathrm{feed}}-P_{\mathrm{clean}})$.')
